#include <vector>
#include <cstddef>
#include <algorithm>
#include <omp.h>

int maxDegree(std::vector<int> const& A, size_t N) {
    // Assume A is an N x N adjacency matrix in row-major order.
    // Degree of node i is sum_j A[i*N + j].
    int globalMax = 0;

    #pragma omp parallel for reduction(max:globalMax) schedule(static)
    for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(N); ++i) {
        int deg = 0;
        const size_t rowBase = static_cast<size_t>(i) * N;
        for (size_t j = 0; j < N; ++j) {
            deg += A[rowBase + j];
        }
        globalMax = std::max(globalMax, deg);
    }

    return globalMax;
}
